const corsHeaders = origin => ({
 "Access-Control-Allow-Origin": origin || "https://joe-dave-operations-intelligence.pages.dev",
 "Access-Control-Allow-Methods": "GET,POST,PUT,DELETE,OPTIONS",
 "Access-Control-Allow-Headers": "Content-Type,Authorization",
 "Access-Control-Max-Age":"86400","Vary":"Origin"
});
const json=(data,status=200,origin)=>new Response(JSON.stringify(data),{status,headers:{...corsHeaders(origin),"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"}});
const uid=()=>crypto.randomUUID();
const hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("");
const digest=async s=>hex(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s)));
const PASSWORD_ITERATIONS=100000;
async function hashPassword(password,saltHex,iterations=PASSWORD_ITERATIONS){
 const salt=saltHex?Uint8Array.from(saltHex.match(/../g).map(x=>parseInt(x,16))):crypto.getRandomValues(new Uint8Array(16));
 const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]);
 const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt,iterations,hash:"SHA-256"},key,256);
 return {stored:"pbkdf2$"+iterations+"$"+hex(salt)+"$"+hex(bits),hash:hex(bits)};
}
async function verifyPassword(password,stored){const p=String(stored||"").split("$"),iterations=Number(p[1]);if(p.length!==4||p[0]!=="pbkdf2"||!Number.isInteger(iterations)||iterations<10000||iterations>PASSWORD_ITERATIONS||!/^[a-f0-9]{32}$/i.test(p[2])||!/^[a-f0-9]{64}$/i.test(p[3]))return false;const actual=(await hashPassword(password,p[2],iterations)).hash,expected=p[3].toLowerCase();let diff=0;for(let i=0;i<expected.length;i++)diff|=actual.charCodeAt(i)^expected.charCodeAt(i);return diff===0;}
async function readJson(req){try{const len=Number(req.headers.get("Content-Length")||0);if(len>1000000)return null;return await req.json();}catch{return null;}}
const validText=(v,max=200)=>typeof v==="string"&&v.trim().length>0&&v.trim().length<=max;
const dateOk=v=>typeof v==="string"&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+"T00:00:00Z"));
async function auth(req,env){const token=(req.headers.get("Authorization")||"").replace(/^Bearer\s+/i,"").trim();if(!/^[a-f0-9]{64}$/i.test(token))return null;const h=await digest(token);return await env.DB.prepare("SELECT u.id,u.email,s.business_id,m.role FROM jd_sessions s JOIN jd_users u ON u.id=s.user_id JOIN jd_business_memberships m ON m.business_id=s.business_id AND m.user_id=u.id WHERE s.token_hash=? AND s.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')").bind(h).first();}
async function ownedBusiness(env,userId,businessId){return await env.DB.prepare("SELECT b.*,m.role AS member_role FROM jd_businesses b JOIN jd_business_memberships m ON m.business_id=b.id WHERE m.user_id=? AND b.id=?").bind(userId,businessId).first();}
function allowedForRole(role,path,method){
 if(role==="owner"||role==="admin")return true;
 if(path.startsWith("/ops/")){
  const p=path.split("/").slice(2),group=p[0]||"",sub=p[1]||"";
  if(group==="hr")return false;
  if(group==="inventory"||group==="manufacturing")return role==="inventory";
  if(group==="crm"||group==="selling"||group==="support")return role==="sales";
  if(group==="buying")return ["accountant","inventory"].includes(role);
  if(group==="projects")return role==="accountant";
  return false;
 }
 if(path==="/business")return method==="GET";
 if(path==="/workspace/members"||path.startsWith("/workspace/members/"))return false;
 if(path==="/workspace/switch")return method==="POST";
 if(path==="/workspace/list")return method==="GET";
 if(path==="/saas/status")return method==="GET";
 const scopedPath=path.startsWith("/invoices/")?"/invoices":path.startsWith("/purchase-orders/")?"/purchase-orders":path.startsWith("/supplier-bills/")?"/supplier-bills":path.startsWith("/bank-transactions/")?"/bank-transactions":path.startsWith("/accounting-periods/")?"/accounting-periods":path;
 if(method==="GET"){
  if(role==="accountant")return true;
  if(role==="sales")return ["/dashboard","/analytics","/customers","/invoices","/receipts"].includes(scopedPath);
  if(role==="inventory")return ["/dashboard","/analytics","/inventory","/inventory/import","/inventory/movements","/purchase-orders","/suppliers"].includes(scopedPath);
  if(role==="viewer")return true;
  return false;
 }
 if(role==="accountant")return ["/customers","/invoices","/receipts","/expenses","/journal","/supplier-bills","/accounting-periods","/bank-accounts","/bank-transactions","/bank-transactions/import"].includes(scopedPath);
 if(role==="sales")return ["/customers","/invoices","/receipts"].includes(scopedPath);
 if(role==="inventory")return ["/inventory","/inventory/import","/inventory/movements","/purchase-orders"].includes(scopedPath);
 return false;
}
async function audit(env,bid,uid0,action,type,id,details={}){await env.DB.prepare("INSERT INTO jd_audit_events(id,business_id,actor_id,action,entity_type,entity_id,details_json) VALUES(?,?,?,?,?,?,?)").bind(uid(),bid,uid0,action,type,id,JSON.stringify(details)).run();}
async function periodIsClosed(env,businessId,date){return !!(await env.DB.prepare("SELECT id FROM jd_accounting_periods WHERE business_id=? AND status='closed' AND ? BETWEEN period_start AND period_end").bind(businessId,date).first());}
async function postJournal(env,{businessId,userId,date,sourceType,sourceId,description,lines}){if(await periodIsClosed(env,businessId,date))throw Error("Accounting period is closed");
 const debit=lines.reduce((s,l)=>s+Number(l.debit_minor||0),0),credit=lines.reduce((s,l)=>s+Number(l.credit_minor||0),0);
 if(lines.length<2||debit!==credit||debit<=0||!Number.isSafeInteger(debit))throw Error("Journal must balance exactly.");
 const id=uid(),stmts=[env.DB.prepare("INSERT INTO jd_journal_entries(id,business_id,entry_date,source_type,source_id,description,status,created_by) VALUES(?,?,?,?,?,?,'draft',?)").bind(id,businessId,date,sourceType,sourceId,description,userId)];
 for(const l of lines)stmts.push(env.DB.prepare("INSERT INTO jd_journal_lines(id,entry_id,account_code,account_name,debit_minor,credit_minor) VALUES(?,?,?,?,?,?)").bind(uid(),id,l.account_code,l.account_name,Number(l.debit_minor||0),Number(l.credit_minor||0)));
 stmts.push(env.DB.prepare("UPDATE jd_journal_entries SET status='posted' WHERE id=? AND business_id=?").bind(id,businessId));
 await env.DB.batch(stmts);return id;
}
